import fs from "node:fs";
import path from "node:path";
import type { Project } from "../shared/schema.ts";
import { audioIdentity, auditNarration, findReusableAudio, type Provider, recordGenerated, textKey, voiceIdentity } from "./audio-manifest.ts";
import { loadSettings, type Settings } from "./paths.ts";
import { freeFileName } from "./persist.ts";
import { elevenLabsSynthesize, piperSynthesize } from "./tts.ts";

export type NarrateResult = {
  /** Clips newly generated by the provider. */
  made: number;
  total: number;
  /** Scenes pointed at audio that already existed elsewhere in the project (no generation). */
  reused: number;
  /** Scenes whose linked audio has no record of its text and was therefore left alone (1-based). */
  keptUnverified: number[];
  /** Scenes whose audio is current but was recorded with a different voice or settings (1-based). */
  voiceDiffers: number[];
};

type Options = {
  only?: number;
  force?: boolean;
  onProgress?: (m: string, pct: number) => void;
  /** Test seams: the self-test narrates with a local fake instead of a real provider. */
  settings?: Settings;
  synthesize?: (text: string, outFile: string) => Promise<void>;
};

/**
 * Generate narration for every scene that has text (or one scene). Files are
 * written to <project>/narration/ and referenced from the project.
 *
 * Existing audio is never overwritten, renamed or deleted:
 *   - audio that already matches the scene's text is kept as it is;
 *   - audio that says the same text elsewhere in the project is reused (so
 *     reordering or renumbering scenes costs nothing);
 *   - linked audio with no record of its text is kept unless `force` is set;
 *   - a new take is always written to a new file name.
 */
export const narrateProject = async (project: Project, dir: string, provider: Provider, opts: Options = {}): Promise<NarrateResult> => {
  const settings = opts.settings ?? loadSettings();
  const voice = voiceIdentity(provider, settings);
  const ext = provider === "piper" ? "wav" : "mp3";
  const result: NarrateResult = { made: 0, total: 0, reused: 0, keptUnverified: [], voiceDiffers: [] };
  const todo = project.scenes.map((s, i) => ({ s, i })).filter(({ s, i }) => s.narration.trim() && (opts.only === undefined || opts.only === i));
  result.total = todo.length;
  for (const [n, { s, i }] of todo.entries()) {
    const conventional = `narration/${String(i + 1).padStart(2, "0")}-${s.id}.${ext}`;
    opts.onProgress?.(`Narrating scene ${i + 1}…`, Math.round((n / todo.length) * 100));
    if (!opts.force) {
      // 1. The audio the scene already points at, then the conventional file name.
      const candidates = [...new Set([s.narrationFile, conventional].filter((f): f is string => !!f))];
      let settled = false;
      for (const file of candidates) {
        const [a] = auditNarration({ ...project, scenes: [{ ...s, narrationFile: file }] }, dir, voice);
        if (a.state === "verified" || a.state === "stamp-match") {
          s.narrationFile = file;
          if (a.voiceMatches === false) result.voiceDiffers.push(i + 1);
          settled = true; break;
        }
        if (a.state === "unverified" && file === s.narrationFile) { result.keptUnverified.push(i + 1); settled = true; break; }
      }
      if (settled) continue;
      // 2. The same words already recorded under another name (scene moved or renumbered).
      const again = findReusableAudio(dir, s.narration, voice, ext);
      if (again) { s.narrationFile = again; result.reused++; continue; }
    }
    // 3. A new take, in a new file. Written under a temporary name first so a
    //    failed or interrupted request can never leave a half-written clip linked.
    const folder = path.join(dir, "narration");
    fs.mkdirSync(folder, { recursive: true });
    const name = freeFileName(folder, path.basename(conventional));
    const abs = path.join(folder, name), part = path.join(folder, `.part-${process.pid}-${name}`);
    try {
      if (opts.synthesize) await opts.synthesize(s.narration, part);
      else if (provider === "piper") await piperSynthesize(s.narration, part, settings);
      else await elevenLabsSynthesize(s.narration, part, settings);
      fs.renameSync(part, abs);
    } finally { fs.rmSync(part, { force: true }); }
    fs.writeFileSync(abs + ".txt", s.narration); // legacy stamp, still read by older versions
    s.narrationFile = `narration/${name}`;
    recordGenerated(dir, { file: s.narrationFile, sceneId: s.id, textSha256: textKey(s.narration), identity: audioIdentity(s.narration, voice), origin: "generated", voice });
    result.made++;
  }
  return result;
};
